// Custom worker entry: the OpenNext handler serves HTTP, and this adds the inbound-SMS queue consumer
// and the production watchdog's cron trigger.
// https://opennext.js.org/cloudflare/howtos/custom-worker
// The import only resolves after a build, so @ts-expect-error would fail whenever .open-next exists.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { consumeInbound, fetchProcessor } from "./src/lib/sms/consumer";
import { scheduledWatchdog } from "./src/lib/watchdog/scheduled";

export default {
  fetch: handler.fetch,

  async queue(batch, env, ctx) {
    // Each text is handed to the app's /process route in-process, so it runs with the same
    // Cloudflare context, env and bundle as every other request.
    const url = new URL(`/api/sms/${env.SMS_WEBHOOK_SECRET}/process`, env.APP_URL);
    await consumeInbound(batch, fetchProcessor((req) => handler.fetch(req, env, ctx), url));
  },

  async scheduled(_controller, env, ctx) {
    // Every minute in production (triggers in wrangler.jsonc). The checks run in the app's
    // /watchdog route, in-process, like the queue consumer's /process.
    await scheduledWatchdog((req) => handler.fetch(req, env, ctx), env);
  },
} satisfies ExportedHandler<CloudflareEnv>;
